insert into public.tm_sheets (id, tm_number, job_id, job_name, employee_id, employee_name, work_date, customer_name, customer_phone, site_address, complaint, work_performed, resolution, labor, materials, photos, markup_rate, tax_rate, labor_total, materials_total, materials_markup, tax_amount, grand_total, customer_sign_name, sign_date, status, created_at) values (pg_temp.d(401), 'EENV261022', pg_temp.d(101), 'Meadowood Med Spa — Tenant Improvement', pg_temp.e('Tanner'), pg_temp.n('Tanner'), '2026-10-22', 'Empire Construction (Meadowood Med Spa)', '', '5000 Smithridge Dr, Reno, NV 89502', 'Owner request: two dedicated 20A circuits in Treatment Room 3 for laser equipment. Not in the original scope.', 'Pulled 2 new #12 homeruns from Panel L1 to Treatment Room 3. Set 2 boxes at 48" AFF per the equipment cut sheet, installed 2 hospital-grade 20A receptacles, and landed them on new 20A breakers. Labeled the circuits.', 'Both circuits are energized and tested. Ready for rough inspection with the rest of the suite.', '[{"name": "Tanner Cox", "rate": 120, "hours": 3.0}, {"name": "Caleb Biondi", "rate": 120, "hours": 3.0}]'::jsonb, '[{"qty": 2, "desc": "20A 1P breaker (Square D QO)", "cost": 14.75, "photo": ""}, {"qty": 2, "desc": "Hospital-grade 20A duplex receptacle", "cost": 22.5, "photo": ""}, {"qty": 2, "desc": "4-sq box w/ 1-gang mud ring", "cost": 6.8, "photo": ""}, {"qty": 180, "desc": "#12 THHN (ft)", "cost": 0.42, "photo": ""}, {"qty": 40, "desc": "3/4\" EMT (ft)", "cost": 0.95, "photo": ""}]'::jsonb, '[{"src": "https://images.unsplash.com/photo-1621905251189-08b45d6a269e?w=1600&h=1200&fit=crop&q=80&auto=format", "caption": "Room 3 homeruns pulled"}]'::jsonb, 30, 8.265, 720.0, 201.7, 60.51, 81.18, 1063.39, 'M. Alvarez (Empire Construction)', '2026-10-22', 'Complete', '2026-10-22 15:45:00-07');
insert into public.tm_sheets (id, tm_number, job_id, job_name, employee_id, employee_name, work_date, customer_name, customer_phone, site_address, complaint, work_performed, resolution, labor, materials, photos, markup_rate, tax_rate, labor_total, materials_total, materials_markup, tax_amount, grand_total, customer_sign_name, sign_date, status, created_at) values (pg_temp.d(402), 'EENV261027', pg_temp.d(104), 'Riverside Grill', pg_temp.e('Caleb'), pg_temp.n('Caleb'), '2026-10-27', 'Riverside Grill', '(775) 555-0142', '17 S Virginia St, Reno, NV 89501', 'The kitchen lighting breaker trips off and on during dinner service.', 'Traced circuit 14 to the junction box above the hood. Found a loose, heat-discolored neutral. Cut back and re-terminated it with new Wago connectors, replaced the 20A breaker, torqued the panel lugs, and ran the circuit under full load for 30 minutes.', 'The circuit is holding under full load. Recommend an IR scan of the panel at the next service visit.', '[{"name": "Caleb Biondi", "rate": 120, "hours": 2.5}]'::jsonb, '[{"qty": 1, "desc": "Wago 221 connector assortment", "cost": 18.5, "photo": ""}, {"qty": 1, "desc": "20A 1P breaker (Square D QO)", "cost": 14.75, "photo": ""}, {"qty": 25, "desc": "#12 THHN (ft)", "cost": 0.42, "photo": ""}]'::jsonb, '[{"src": "https://images.unsplash.com/photo-1566417110090-6b15a06ec800?w=1600&h=1200&fit=crop&q=80&auto=format", "caption": "Panel before re-torque"}, {"src": "https://images.unsplash.com/photo-1652715564391-38cc4475b7f5?w=1600&h=1200&fit=crop&q=80&auto=format", "caption": "Junction box above hood"}]'::jsonb, 30, 8.265, 300.0, 43.75, 13.12, 29.5, 386.37, 'Maria Lopez (GM)', '2026-10-27', 'Complete', '2026-10-27 15:45:00-07');
insert into public.tm_sheets (id, tm_number, job_id, job_name, employee_id, employee_name, work_date, customer_name, customer_phone, site_address, complaint, work_performed, resolution, labor, materials, photos, markup_rate, tax_rate, labor_total, materials_total, materials_markup, tax_amount, grand_total, customer_sign_name, sign_date, status, created_at) values (pg_temp.d(403), 'EENV261029', pg_temp.d(102), 'Sparks Distribution Center — LED Retrofit', pg_temp.e('Tyler'), pg_temp.n('Tyler'), '2026-10-29', 'Empire Construction (Sparks Distribution Center)', '', '1150 Glendale Ave, Sparks, NV 89431', 'Damaged fixture whip at bay 9 found during the LED retrofit. Not in the retrofit scope.', 'Replaced 12 ft of crushed 12/2 MC whip and both connectors at bay 9. Re-hung the fixture on new chain and tested it.', 'Fixture is operating normally. Noted on the retrofit punch list.', '[{"name": "Tyler Glider", "rate": 120, "hours": 1.5}, {"name": "Tanner Cox", "rate": 120, "hours": 1.5}]'::jsonb, '[{"qty": 12, "desc": "12/2 MC cable (ft)", "cost": 1.15, "photo": ""}, {"qty": 2, "desc": "MC connector, 3/8\"", "cost": 2.4, "photo": ""}, {"qty": 1, "desc": "Jack chain + S-hooks", "cost": 9.6, "photo": ""}]'::jsonb, '[{"src": "https://images.unsplash.com/photo-1615774925655-a0e97fc85c14?w=1600&h=1200&fit=crop&q=80&auto=format", "caption": "Bay 9 after repair"}]'::jsonb, 30, 8.265, 360.0, 28.2, 8.46, 32.78, 429.44, 'M. Alvarez (Empire Construction)', '2026-10-29', 'Complete', '2026-10-29 15:45:00-07');
